def choose_move(observation):
    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pair(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def is_seq(v):
        return isinstance(v, (list, tuple))

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp(b[0] - a[0]), clamp(b[1] - a[1])]

    def step_away(a, b):
        return [clamp(a[0] - b[0]), clamp(a[1] - b[1])]

    def as_points(v):
        out = []
        if is_seq(v):
            for item in v:
                if is_seq(item) and len(item) >= 2:
                    out.append((item[0], item[1]))
        return out

    def best_by(points, score_fn, reverse=False):
        if not points:
            return None
        best = points[0]
        best_score = score_fn(best)
        for p in points[1:]:
            s = score_fn(p)
            if (s > best_score) if reverse else (s < best_score):
                best, best_score = p, s
        return best

    env = observation.get("environment_name", "") or ""
    role = observation.get("self_role", "") or ""

    me = pair(observation.get("self_position"))
    opp = pair(observation.get("opponent_position"), me)
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    resources = as_points(observation.get("resources"))
    unclaimed = as_points(observation.get("unclaimed_cells"))
    opp_terr = as_points(observation.get("opponent_territory"))
    own_terr = as_points(observation.get("self_territory"))
    obstacles = set(as_points(observation.get("walls")) + as_points(observation.get("obstacles")))

    def legal_step(step):
        return [clamp(step[0]), clamp(step[1])]

    def score_resource(p):
        return dist(me, p) + max(0, 2 - dist(opp, p))

    def score_unclaimed(p):
        return dist(me, p) * 2 - dist(opp, p)

    def score_opp_terr(p):
        return dist(me, p) * 2 - dist(opp, p) + 1

    def score_escape_corner(c):
        return dist(opp, c) - dist(me, c)

    # Pursuit / evasion
    if env == "pursuit_evasion":
        if role == "pursuer":
            move = step_toward(me, opp)
            if move == [0, 0]:
                if w and h:
                    center = ((w - 1) // 2, (h - 1) // 2)
                    move = step_toward(me, center)
            return legal_step(move)

        # evader: maximize distance from opponent, prefer corners/edges
        candidates = []
        if w and h:
            candidates = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1),
                          (0, me[1]), (w - 1, me[1]), (me[0], 0), (me[0], h - 1)]
        if not candidates:
            candidates = [(me[0] - 3, me[1] - 3), (me[0] - 3, me[1] + 3), (me[0] + 3, me[1] - 3), (me[0] + 3, me[1] + 3)]
        target = best_by(candidates, score_escape_corner, reverse=True)
        return legal_step(step_toward(me, target))

    # Territory control
    if env == "territory_control":
        if unclaimed:
            target = best_by(unclaimed, score_unclaimed)
            return legal_step(step_toward(me, target))
        if opp_terr:
            target = best_by(opp_terr, score_opp_terr)
            return legal_step(step_toward(me, target))
        if own_terr:
            # drift toward frontier by moving toward farthest own territory cell from opponent
            target = best_by(own_terr, lambda p: dist(opp, p) - dist(me, p), reverse=True)
            return legal_step(step_toward(me, target))
        if w and h:
            center = ((w - 1) // 2, (h - 1) // 2)
            return legal_step(step_toward(me, center))
        return [0, 0]

    # Resource collection
    if resources:
        # Prefer resources closer to me, but not trivially intercepted by opponent
        target = best_by(resources, score_resource)
        return legal_step(step_toward(me, target))

    # Generic fallback: pressure opponent unless already overlapping
    if me != opp:
        # Slightly favor moving away if very close and no objectives
        if dist(me, opp) <= 2 and (w or h):
            move = step_away(me, opp)
            if move != [0, 0]:
                return legal_step(move)
        return legal_step(step_toward(me, opp))

    if w and h:
        center = ((w - 1) // 2, (h - 1) // 2)
        return legal_step(step_toward(me, center))

    return [0, 0]

